files.content:
.root {
  --vt-surface: #FFFFFF;
  --vt-surface-2: #F9F9F9;
  --vt-surface-deep: #000000;
  --vt-ink: #000000;
  --vt-ink-soft: #717275;
  --vt-on-deep: #FFFFFF;
  --vt-accent: #247cff;
  --vt-on-accent: #000000;
  --vt-accent-ink: #000000;
  --vt-accent-on-deep: #247cff;
  --vt-line: #eaeaea;

  font-family: 'Open Sans', system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  background: var(--vt-surface);
  color: var(--vt-ink);
  overflow-x: hidden;
  box-sizing: border-box;
}

.root *,
.root *::before,
.root *::after {
  box-sizing: border-box;
}

.root a:focus-visible {
  outline: 2px solid var(--vt-accent);
  outline-offset: 2px;
}

.nav {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  background: var(--vt-surface);
  box-shadow: 0 0.5rem 1rem rgba(0, 0, 0, 0.15);
  z-index: 1030;
  padding: 20px 0;
}

.navIn {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 15px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 1rem;
}

.logo {
  order: 2;
  flex: 0 0 auto;
}

.navGroup {
  display: flex;
  gap: 1.5rem;
  flex: 1 1 0;
}

.navGroup:first-child {
  justify-content: flex-start;
}

.navGroup:last-child {
  justify-content: flex-end;
}

.navGroup a {
  color: var(--vt-ink-soft);
  font-weight: 600;
  font-size: 16px;
  text-decoration: none;
  padding: 15px 0;
  transition: color 0.3s;
}

.navGroup a:hover {
  color: var(--vt-ink);
}

.hero {
  position: relative;
  margin-top: 94px;
  height: 580px;
}

.heroSlides {
  display: flex;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  height: 100%;
  background: var(--vt-surface-deep);
}

.heroSlide {
  flex: 0 0 100%;
  scroll-snap-align: start;
  height: 100%;
}

.heroSlide img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.heroText {
  position: absolute;
  bottom: 0;
  right: 0;
  z-index: 2;
  width: 50%;
  padding: 1.5rem 2.5rem;
  background: var(--vt-surface);
  display: flex;
  flex-direction: column;
  justify-content: center;
}

.heroText h1 {
  color: var(--vt-ink);
  font-size: 48px;
  font-weight: 700;
  margin-top: auto;
  margin-bottom: 0.5rem;
  line-height: normal;
}

.heroText p {
  color: var(--vt-ink-soft);
  font-size: 18px;
  font-weight: 300;
  letter-spacing: 0.5px;
  margin-bottom: 1rem;
}

.heroLinks {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 1rem;
}

.customLink {
  display: inline-block;
  text-decoration: none;
  border: 1px solid var(--vt-line);
  color: var(--vt-accent);
  font-weight: 600;
  line-height: 40px;
  padding: 0 30px;
  text-transform: uppercase;
  position: relative;
  overflow: hidden;
  transition: all 0.3s;
  background: transparent;
}

.customLink:hover {
  background: var(--vt-line);
}

.customLink::before {
  content: attr(data-hover);
  background-color: var(--vt-line);
  color: var(--vt-accent);
  position: absolute;
  top: 100%;
  bottom: 0;
  left: 0;
  transition: all 300ms cubic-bezier(0.19, 1, 0.56, 1);
  right: 0;
  text-align: center;
}

.customLink:hover::before {
  top: 0;
}

.contactPhone {
  font-weight: 600;
  color: var(--vt-ink);
}

.sectionPadding {
  padding: 7rem 0;
}

.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 15px;
  width: 100%;
}

.aboutRow {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 2rem;
}

.aboutText {
  flex: 1 1 50%;
}

.aboutText h2 {
  color: var(--vt-ink);
  font-size: 36px;
  font-weight: 700;
  margin-bottom: 1rem;
}

.aboutText p {
  color: var(--vt-ink-soft);
  font-size: 18px;
  font-weight: 300;
  letter-spacing: 0.5px;
  margin-bottom: 1rem;
}

.aboutImage {
  flex: 0 0 350px;
  width: 350px;
  height: 350px;
  border-radius: 50%;
  overflow: hidden;
  background: var(--vt-surface);
  box-shadow: 0 1rem 3rem rgba(0, 0, 0, 0.175);
  display: flex;
  align-items: center;
  justify-content: center;
}

.aboutImage img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.gallery {
  display: flex;
}

.galleryRow {
  display: flex;
  width: 100%;
}

.galleryItem {
  flex: 1 1 50%;
  padding: 0;
}

.galleryItem img {
  width: 100%;
  height: auto;
  display: block;
  object-fit: cover;
}

.timelineSection {
  padding-bottom: 5rem;
}

.timelineTitle {
  text-align: center;
  color: var(--vt-ink);
  font-size: 36px;
  font-weight: 700;
  margin-bottom: 3rem;
}

.timeline {
  position: relative;
}

.timeline::before {
  content: "";
  position: absolute;
  top: 37px;
  left: 50%;
  width: 0;
  border-left: 1px solid var(--vt-line);
  height: 85%;
  transform: translateX(-50%);
  z-index: 1;
}

.timelineNode {
  position: relative;
  display: grid;
  grid-template-columns: 5fr 1fr 5fr;
  align-items: start;
  margin-bottom: 2rem;
}

.timelineNode.odd .timelineContent {
  grid-column: 1;
  text-align: right;
}

.timelineNode.odd .timelineIcon {
  grid-column: 2;
}

.timelineNode.odd .timelineDate {
  grid-column: 3;
  text-align: left;
}

.timelineNode.even .timelineContent {
  grid-column: 3;
  text-align: left;
}

.timelineNode.even .timelineIcon {
  grid-column: 2;
}

.timelineNode.even .timelineDate {
  grid-column: 1;
  text-align: right;
}

.timelineContent {
  background: var(--vt-surface);
  box-shadow: 0 0.5rem 1rem rgba(0, 0, 0, 0.15);
  border-radius: 0 0 0.25rem 0.25rem;
  padding: 0;
  position: relative;
}

.timelineContent h3 {
  background: var(--vt-surface-deep);
  color: var(--vt-on-deep);
  padding: 10px 30px;
  border-radius: 0.25rem 0.25rem 0 0;
  font-size: 26px;
  font-weight: 600;
  margin: 0;
  position: relative;
}

.timelineNode.odd .timelineContent h3::after {
  content: "";
  position: absolute;
  top: 50%;
  left: 100%;
  transform: translate(0, -50%);
  width: 0;
  border-left: 10px solid var(--vt-surface-deep);
  border-top: 10px solid transparent;
  border-bottom: 10px solid transparent;
}

.timelineNode.even .timelineContent h3::after {
  content: "";
  position: absolute;
  top: 50%;
  right: 100%;
  transform: translate(0, -50%);
  width: 0;
  border-right: 10px solid var(--vt-surface-deep);
  border-top: 10px solid transparent;
  border-bottom: 10px solid transparent;
}

.timelineContent p {
  padding: 10px 30px;
  color: var(--vt-ink-soft);
  font-size: 18px;
  font-weight: 300;
  margin: 0;
}

.timelineIcon {
  position: relative;
  z-index: 100;
  text-align: center;
  line-height: 80px;
  font-size: 32px;
  color: var(--vt-accent);
}

.timelineIcon::before {
  content: "";
  position: absolute;
  top: 0;
  left: 50%;
  transform: translateX(-50%);
  width: 80px;
  height: 80px;
  border-radius: 50%;
  background: var(--vt-surface);
  box-shadow: 0 1rem 3rem rgba(0, 0, 0, 0.175);
  z-index: -1;
}

.timelineDate {
  padding: 10px 0;
  color: var(--vt-ink-soft);
  font-size: 16px;
}

.siteFooter {
  background: var(--vt-surface-2);
  padding: 7rem 0;
}

.footerRow {
  display: flex;
  flex-wrap: wrap;
  gap: 2rem;
}

.footerColHours {
  flex: 0 0 40%;
}

.footerColClinic {
  flex: 0 0 20%;
}

.footerColSocials {
  flex: 0 0 25%;
}

.footerColCopyright {
  flex: 0 0 100%;
  margin-top: 1rem;
}

.footerRow h5 {
  color: var(--vt-ink);
  font-size: 20px;
  font-weight: 600;
  margin-bottom: 1rem;
}

.footerColHours p,
.footerColClinic p {
  color: var(--vt-ink-soft);
  font-size: 16px;
  font-weight: 300;
  margin-bottom: 0.5rem;
}

.footerColClinic a {
  color: var(--vt-ink-soft);
  text-decoration: none;
  transition: color 0.3s;
}

.footerColClinic a:hover {
  color: var(--vt-accent);
}

.socialLinks a {
  color: var(--vt-ink-soft);
  margin-right: 15px;
  font-size: 18px;
  transition: color 0.3s;
}

.socialLinks a:hover {
  color: var(--vt-accent);
}

.copyrightText {
  color: var(--vt-ink-soft);
  font-size: 16px;
}

@media (max-width: 991px) {
  .navIn {
    flex-direction: column;
    align-items: center;
    gap: 0;
  }

  .navGroup {
    flex-direction: column;
    align-items: center;
    gap: 5px;
    width: 100%;
  }

  .navGroup a {
    padding: 5px 0;
  }

  .logo {
    order: -1;
    margin-bottom: 5px;
  }

  .hero {
    margin-top: 74px;
    height: auto;
  }

  .heroSlides {
    height: auto;
  }

  .heroText {
    position: relative;
    bottom: auto;
    right: auto;
    width: 100%;
    padding: 2rem;
  }

  .aboutRow {
    flex-direction: column;
  }

  .aboutImage {
    flex: 0 0 320px;
    width: 320px;
    height: 320px;
  }
}

@media (max-width: 767px) {
  .heroText {
    padding: 1.5rem;
  }

  .timeline::before {
    top: 60px;
    left: 33px;
    height: 90%;
    transform: none;
  }

  .timelineNode {
    display: block;
    margin-left: 60px;
    margin-bottom: 2rem;
  }

  .timelineNode.odd .timelineContent,
  .timelineNode.even .timelineContent {
    text-align: left;
    margin-left: 0;
  }

  .timelineNode.odd .timelineIcon,
  .timelineNode.even .timelineIcon {
    position: absolute;
    left: -60px;
    top: 0;
  }

  .timelineNode.odd .timelineDate,
  .timelineNode.even .timelineDate {
    text-align: left;
    margin-left: 0;
  }

  .timelineNode.odd .timelineContent h3::after,
  .timelineNode.even .timelineContent h3::after {
    display: none;
  }

  .galleryRow {
    flex-direction: column;
  }

  .galleryItem {
    flex: 1 1 auto;
  }

  .footerRow {
    flex-direction: column;
  }

  .footerColHours,
  .footerColClinic,
  .footerColSocials,
  .footerColCopyright {
    flex: 0 0 100%;
    width: 100%;
  }
}

@media (max-width: 480px) {
  .heroText {
    padding: 1rem;
  }

  .aboutImage {
    flex: 0 0 235px;
    width: 235px;
    height: 235px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .heroSlides {
    scroll-behavior: auto;
  }

  .customLink,
  .customLink::before {
    transition: none;
  }
}
